@Composable fun SectionItem( modifier: Modifier = Modifier, leadingIcon: ImageVector, trailingIcon: ImageVector? = null, title: String, onClick: () -> Unit = { }, onLongClick: () -> Unit = { }, iconTint: Color = MaterialTheme.colorScheme.onSurfaceVariant, textColor: Color = MaterialTheme.colorScheme.onSurface ) { Row( modifier = modifier .fillMaxWidth() .combinedClickable( onClick = onClick, onLongClick = { // Example: Open calendar app (placeholder, implement actual logic as needed) onLongClick() } ) .padding(vertical = 16.dp, horizontal = 20.dp) , verticalAlignment = Alignment.CenterVertically
) { Icon( imageVector = leadingIcon, contentDescription = null, tint = iconTint ) HSpacer(15.dp) Text( text = title, color = textColor, style = MaterialTheme.typography.bodyLarge, )
Spacer(modifier = Modifier.weight(1f))
if (trailingIcon != null){ Icon( imageVector = trailingIcon, contentDescription = null, tint = iconTint ) } } }

